	tests := []struct {
		name string
		args []string
	}{
		{name: "no arguments", args: nil},
		{name: "one argument", args: []string{"summary"}},
		{name: "many arguments", args: []string{"summary", "log.jsonl", "--target", "x"}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var stdout, stderr bytes.Buffer
			if got := Run(tt.args, &stdout, &stderr); got != 0 {
				t.Errorf("Run(%q) = %d, want 0", tt.args, got)
			}
		})
	}
}

